{
  "name": "KA系列可编程直流电源",
  "name_en": "KA Series Programmable DC Bench Power Supply",
  "manufacturer": "",
  "description": "KA系列台式可编程直流稳压电源，可设定输出电压与电流限值，并测量输出电压、电流和功率，常用于电子电路供电、器件测试、实验教学以及台式研发调试。",
  "description_en": "A KA-series programmable bench DC power supply used to provide regulated DC power with configurable voltage and current limit, and to measure output voltage, current, and power. It is commonly used for circuit powering, device testing, teaching labs, and bench-top R&D troubleshooting.",
  "tag_hints": [
    "programmable DC power supply",
    "bench power supply",
    "regulated DC output",
    "voltage and current limit",
    "electronic circuit testing",
    "lab power source"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化电源并准备受控使用。",
      "description_en": "Initialize the power supply for controlled operation."
    },
    {
      "action_name": "auto-lock_commands",
      "description": "设置命令/面板锁定状态；该机型在USB连接时通常会自动锁定前面板。",
      "description_en": "Set the command/front-panel lock state; this model typically auto-locks the front panel when connected over USB."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量输出电流。",
      "description_en": "Measure the output current."
    },
    {
      "action_name": "auto-measure_power",
      "description": "测量输出功率。",
      "description_en": "Measure the output power."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量输出电压。",
      "description_en": "Measure the output voltage."
    },
    {
      "action_name": "auto-remote_sense",
      "description": "设置远端感测状态；该机型通常不支持远端感测。",
      "description_en": "Set the remote-sense state; this model typically does not support remote sensing."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置输出电流限值。",
      "description_en": "Set the output current limit."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置输出电压。",
      "description_en": "Set the output voltage."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "打开或关闭电源输出。",
      "description_en": "Turn the power output on or off."
    }
  ]
}

